questions['DNS and DHCP'].push(['What is a DHCP lease?',['Temporary address configuration grant','MAC vendor record','DNS zone transfer','TCP session'],0,'DHCP leases have a lifetime and renewal process.',2],['Which DNS record maps a name to IPv6?',['A','AAAA','MX','PTR'],1,'AAAA records carry IPv6 addresses.',2],['What is a recursive resolver responsible for?',['Finding an answer on behalf of a client','Assigning VLAN IDs','Learning switch MACs','Issuing TCP ACKs'],0,'A recursive resolver follows DNS delegation/cache to obtain an answer.',3]);
