const quizTopics=['All topics',...Object.keys(questions)];function quizPage(){let html=back()+head('KNOWLEDGE CHECK','Network quiz centre','Choose a topic and difficulty. Your results are saved to your account, with revision suggestions after each attempt.')+`<div class="panel"><div class="row"><label class="muted-text">TOPIC</label><select id="qTopic" class="field">${quizTopics.map(x=>`<option>${x}</option>`).join('')}</select><label class="muted-text">LEVEL</label><select id="qLevel" class="field"><option value="1">Level 1 · Beginner</option><option value="2">Level 2 · Intermediate</option><option value="3">Level 3 · Advanced</option></select><button class="btn accent" onclick="startQuiz()">Start quiz →</button></div><p>Pass target: 70%. If you do not pass, NetViz recommends the related simulator to revisit.</p></div><div id="quizArea" style="margin-top:15px"></div>`;$('#view').innerHTML=html}
function startQuiz(){let topic=$('#qTopic').value;let level=+$('#qLevel').value;let pool=topic==='All topics'?Object.entries(questions).flatMap(([k,v])=>v.filter(q=>(q[4]||1)<=level).map(q=>[k,...q])):questions[topic].filter(q=>(q[4]||1)<=level).map(q=>[topic,...q]);quiz={topic,level,index:0,score:0,missed:[],questions:pool.sort(()=>Math.random()-.5).slice(0,Math.min(10,pool.length))};renderQuestion()}
function renderQuestion(){let q=quiz.questions[quiz.index];if(!q)return;let [topic,question,opts,answer,explain]=q;$('#quizArea').innerHTML=`<div class="panel"><div class="row between"><span class="eyebrow">QUESTION ${quiz.index+1} / ${quiz.questions.length} · ${topic}</span><b>${quiz.score} correct</b></div><div class="progress" style="margin:13px 0"><span style="width:${quiz.index/quiz.questions.length*100}%"></span></div><h3 style="font-size:17px;margin:20px 0">${question}</h3><div id="options">${opts.map((o,i)=>`<button class="quiz-option" onclick="answerQuiz(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div><p id="feedback"></p><button id="quizNext" class="btn accent hidden" onclick="nextQuestion()">Next question →</button></div>`}
function answerQuiz(i){let q=quiz.questions[quiz.index],correct=i===q[3];if(correct)quiz.score++;else if(!quiz.missed.includes(q[0]))quiz.missed.push(q[0]);document.querySelectorAll('.quiz-option').forEach((b,j)=>{b.disabled=true;if(j===q[3])b.classList.add('correct');else if(j===i)b.classList.add('wrong')});$('#feedback').textContent=(correct?'Correct! ':'Not quite. ')+q[4];$('#quizNext').classList.remove('hidden')}
async function nextQuestion(){quiz.index++;if(quiz.index<quiz.questions.length){renderQuestion();return}let pct=Math.round(quiz.score/quiz.questions.length*100),passed=pct>=70;try{await api('/api/scores',{method:'POST',body:JSON.stringify({topic:quiz.topic,level:quiz.level,score:quiz.score,total:quiz.questions.length})})}catch(e){toast(e.message)}let topicToPage={'IP addressing':'ip','TCP and UDP':'tcp','DNS and DHCP':'dns','Network devices':'topology','Wireless and mobile':'mobile','VLAN & switching':'topology','Routing & ACL':'topology','Network services':'dhcp','Network security':'topology'};let suggestion=topicToPage[quiz.missed[0]||quiz.topic]||'topology';$('#quizArea').innerHTML=`<div class="panel"><div class="eyebrow">QUIZ COMPLETE</div><h2 style="font-size:30px">${pct}%</h2><h3>${passed?'Well done — level passed!':'Keep practising — revisit these concepts.'}</h3><p>You answered ${quiz.score} of ${quiz.questions.length} correctly. ${passed?'You met the 70% pass target.':'Your recommended revision area is '+(quiz.missed[0]||quiz.topic)+'.'}</p><div class="progress"><span style="width:${pct}%"></span></div><div class="row" style="margin-top:18px"><button class="btn accent" onclick="go('${suggestion}')">${passed?'Explore next':'Relearn recommended topic'} →</button><button class="btn" onclick="startQuiz()">Try again</button></div></div>`}
api('/api/me').then(d=>{if(d.loggedIn)enter(d.username)}).catch(()=>{});

async function runDhcpLease(){
 const network=$('#dhcpPool')?.value||'192.168.10.0/24';
 try{const d=await api('/api/dhcp/lease',{method:'POST',body:JSON.stringify({network,client_id:$('#dhcpClient')?.value||'Naveen-PC'})});
 const log=$('#dhcpLog')||$('#protoLog');if(log)log.textContent=d.dora.map((x,i)=>`${i+1}. ${x.message}: ${x.detail}`).join('\n')+`\n\nLEASED ADDRESS ${d.lease.address}\nMASK ${d.lease.mask}\nGATEWAY ${d.lease.gateway}\nDNS ${d.lease.dns}\nDURATION ${d.lease.duration}`;
 }catch(e){toast(e.message)}
}
